ee:message.ee:set-payload:
%dw 2.0
output application/json
var src = payload.objConfiguracionInventario
var code = payload.cod_res as Number
---
{
	status: code,
	code: if ( code == 200 ) "OK" else "Error",
	message: {
		message: if ( code == 200 ) "Successful Transaction."  else payload.res default "Error Transaction."
	},
	inventoryConfiguration: {
		serviceAccount: (src.serviceAccounts default []) map (sa) -> {
			id: sa.serviceAccountId,
			place: (sa.addresses default []) map (addr) -> {
				resourceAccess: (addr.accesses default []) map (acc) -> {
					id: acc.accessId,
					technology: acc.technologyName,
					resourceRoute: {
						resource: (acc.detailedRoute.elements default []) map (el) -> {
							id: el.elementId,
							"type": el.elementType,
							name: el.hostName,
							port: el.port,
							vendor: el.vendor,
							location: el.networkLocation,
							characteristic: (el.attributes default []) map (att) -> {
								name: att.name,
								value: att.value
							}
						}
					},
					characteristic: (acc.attributes default []) map (att) -> {
						name: att.name,
						value: att.value
					}
				},
				service: (addr.services default []) map (srv) -> {
					id: srv.serviceId,
					rootServiceId: srv.rootServiceId,
					parentServiceId: srv.parentServiceId,
					name: srv.serviceName,
					state: srv.serviceStatus,
					characteristic: (srv.attributes default []) map (att) -> {
						name: att.name,
						value: att.value,
						action: att.action
					}
				},
				policy: (addr.policies default []) map (pol) -> {
					resourcePolicy: (pol.equipmentPolicies default []) map (eq) -> {
						resourceType: eq.equipmentType,
						brand: eq.brand,
						model: eq.model,
						minQuantity: eq.minimumQuantity,
						characteristic: (eq.attributes default []) map (att) -> {
							name: att.name,
							value: att.value
						}
					}
				}
			}
		}
	}
}
